import { resolveSignedURLKey } from '@payloadcms/plugin-cloud-storage/utilities';
import { APIError, Forbidden } from 'payload';
import { assertClientUploadAllowed } from 'payload/internal';
import { passesMakeViewerWriteGate } from '../../plugin/make-permission-access/make-permission-access.js';
const defaultAccess = ({ req })=>Boolean(req.user) && passesMakeViewerWriteGate(req.user);
/**
 * v4 client-upload entry point. Payload core calls this from
 * `POST /api/upload-instructions`; we sign a Content API upload URL and hand the
 * browser an `http` PUT instruction plus a signed upload receipt.
 *
 * Each upload gets its own `_objectKey`, so it never overwrites another object.
 * Payload verifies the receipt before it reads the uploaded file back through
 * `staticHandler`, and it does not upload the original again in `handleUpload`.
 */ export const getGenerateUploadInstructions = ({ access = defaultAccess, client, collectionPrefix = '' })=>{
    const generate = async ({ collectionSlug, docPrefix, filename, filesize, mimeType, overrideAccess, req })=>{
        if (!overrideAccess && !await access({
            collectionSlug,
            req
        })) {
            throw new Forbidden();
        }
        assertClientUploadAllowed({
            collection: req.payload.collections[collectionSlug]?.config,
            filename,
            mimeType
        });
        const { sanitizedFilename, storageFilePath, uploadReference } = await resolveSignedURLKey({
            collectionPrefix,
            collectionSlug,
            docPrefix,
            filename,
            req
        });
        const { data, error, response } = await client.POST('/api/v0/uploads/sign', {
            body: {
                collectionId: collectionSlug,
                contentType: mimeType,
                expiresIn: 3600,
                filename: storageFilePath
            }
        });
        if (error) {
            throw new APIError(`Failed to get presigned upload URL: ${error.message}`, response.status, {
                code: error.code
            });
        }
        if (!data) {
            throw new Error('No response while getting presigned upload URL');
        }
        return {
            type: 'http',
            file: {
                filename: sanitizedFilename,
                mimeType,
                size: filesize,
                uploadReference
            },
            // The presigned URL is signed with `contentType: mimeType`, so the browser
            // PUT must carry a matching Content-Type header or S3 rejects the signature.
            request: {
                headers: {
                    'Content-Type': mimeType
                },
                method: 'PUT',
                url: data.url
            }
        };
    };
    return generate;
};
